// android/build.gradle.kts
// Root build file: declares plugins only. Real configuration lives per module, so a UI dependency
// can never sneak into :core and make the brain untestable without an emulator.
plugins {
    alias(libs.plugins.android.application) apply false
    alias(libs.plugins.android.library) apply false
    alias(libs.plugins.kotlin.android) apply false
    alias(libs.plugins.kotlin.jvm) apply false
    alias(libs.plugins.kotlin.serialization) apply false
    alias(libs.plugins.compose.compiler) apply false
}

// The catalogue and i18n assets are generated by the Node workspace, not by Gradle. This task is a
// reminder hook: if the generated asset is missing, `:core:test` will fail on an absent file with a
// message that names the command to run.
tasks.register("checkGeneratedAssets") {
    group = "verification"
    description = "Fails when android/core/src/main/assets is not up to date (run npm run catalogue:build)"
    doLast {
        val assets = layout.projectDirectory.dir("core/src/main/assets").asFile
        val required = listOf("catalogue.json", "i18n/hi.json", "i18n/en.json")
        val missing = required.filter { !File(assets, it).exists() }
        if (missing.isNotEmpty()) {
            throw GradleException(
                "Missing generated assets: $missing\n" +
                    "   Fix from the repo root:  npm ci && npm run catalogue:build && npm run i18n:parity",
            )
        }
    }
}
